What is logged when this tree mounts? (Production build, no StrictMode.)

```jsx
function Child({ name }) {
  useEffect(() => { console.log('effect ' + name); });
  console.log('render ' + name);
  return null;
}

function Parent() {
  useEffect(() => { console.log('effect Parent'); });
  console.log('render Parent');
  return <><Child name="A" /><Child name="B" /></>;
}
```

The user clicks the counter three times, then `isA` flips to false. What does the screen show?

```jsx
function Counter({ label = '' }) {
  const [n, setN] = useState(0);
  return <span onClick={() => setN(n + 1)}>{label}{n}</span>;
}

function App({ isA }) {
  return <div>{isA ? <Counter label="A" /> : <Counter label="B" />}</div>;
}
```

A counter inside the layout below has reached 2. Then `compact` becomes true. What does the counter show?

```jsx
function Counter({ label = '' }) {
  const [n, setN] = useState(0);
  return <span onClick={() => setN(n + 1)}>{label}{n}</span>;
}

function Layout({ compact }) {
  return compact
    ? <section><Counter /></section>
    : <div><Counter /></div>;
}
```

