The user clicks the inner counter three times. Then the outer component re-renders for an unrelated reason. What does the counter show, and why?

```jsx
function Outer() {
  const [theme, setTheme] = useState('light');

  function Inner() {
    const [n, setN] = useState(0);
    return <button onClick={() => setN(n + 1)}>{n}</button>;
  }

  return <div className={theme}><Inner /></div>;
}
```

Both A and B render `<Counter />`. The counter is at 2 when `mode` switches from "a" to "b". What is shown?

```jsx
function Counter({ label = '' }) {
  const [n, setN] = useState(0);
  return <span onClick={() => setN(n + 1)}>{label}{n}</span>;
}

function A() { return <Counter />; }
function B() { return <Counter />; }

function App({ mode }) {
  return <div>{mode === 'a' ? <A /> : <B />}</div>;
}
```

Clicking the div updates Wrapper's state. Which components re-render? (Production build, no memo anywhere.)

```jsx
function Leaf() { console.log('Leaf'); return null; }
function ChildA() { console.log('ChildA'); return null; }

function Wrapper({ children }) {
  const [n, setN] = useState(0);
  console.log('Wrapper');
  return <div onClick={() => setN(n + 1)}>{children}<Leaf /></div>;
}

function Top() {
  console.log('Top');
  return <Wrapper><ChildA /></Wrapper>;
}
```

