The parent changes the `items` prop once. What does List log for that update? (Production build.)

```jsx
function List({ items }) {
  const [prevItems, setPrevItems] = useState(items);
  const [selection, setSelection] = useState('x');

  if (items !== prevItems) {
    setPrevItems(items);
    setSelection(null);
  }

  console.log('selection=' + selection);
  return null;
}
```

