Clicking the button changes the Provider's value. What is logged? (Production build, no memo.)

```jsx
const Ctx = createContext(0);

function Consumer() {
  const v = useContext(Ctx);
  console.log('Consumer ' + v);
  return null;
}
function Middle() { console.log('Middle'); return <Consumer />; }

function Top({ children }) {
  const [v, setV] = useState(0);
  console.log('Top');
  return (
    <Ctx.Provider value={v}>
      <button onClick={() => setV(v + 1)} />
      {children}
    </Ctx.Provider>
  );
}

function App() { return <Top><Middle /></Top>; }
```

After mount, the user clicks the button once. How many component functions run during that update? Type a number. (Production build, no memo.)

```jsx
function Sidebar() { return <nav />; }
function Content() { return <main />; }
function Footer() { return <footer />; }

function Layout({ sidebar, children }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button onClick={() => setOpen(!open)} />
      {sidebar}
      {children}
      <Footer />
    </div>
  );
}

function App() {
  return <Layout sidebar={<Sidebar />}><Content /></Layout>;
}
```
